 marks=[c for rr,c in ones if rr==r]
 if not marks or all(c<min(rect_cols) for c in marks):
  for c in range(max(rect_cols)+1,W):
   if (r,c) not in ones:g[r][c]=2
 if not marks or all(c>max(rect_cols) for c in marks):
  for c in range(min(rect_cols)):
   if (r,c) not in ones:g[r][c]=2
# Each rectangle column similarly projects away from a 1 above/below it.
for c in rect_cols:
 marks=[r for r,cc in ones if cc==c]
 if not marks or all(r<min(rect_rows) for r in marks):
  for r in range(max(rect_rows)+1,H):
   if (r,c) not in ones:g[r][c]=2
 if not marks or all(r>max(rect_rows) for r in marks):
  for r in range(min(rect_rows)):
